1	import { expect, test } from "@playwright/test";
2	import { DOCK_COLOR, FOG_COLOR, LAND_COLORS, SEA_COLOR, SHOAL_COLOR } from "../../apps/web/src/palette.js";
3	import { compassHeading, dockLabel, isNavigable, seaMap, shipTuning, SIGHT_RADIUS_TILES, Terrain, terrainAt } from "../../packages/content/src/index.js";
4	import {
5	  attachScreenshot,
6	  clearCourse,
7	  colourAt,
8	  createMatch,
9	  dockHintsSeen,
10	  drawnIds,
11	  fogRevealed,
12	  joinMatch,
13	  listedIds,
14	  minimapShows,
15	  onCanvas,
16	  ownColour,
17	  ownDrawnPosition,
18	  place,
19	  readout,
20	  recordDockHints,
21	  sailTo,
22	  selfId,
23	  shipsOnCanvas,
24	  tileColourShare,
25	  TILE,
26	  turnTo,
27	} from "./helpers.js";
28	
29	// Sailing with the keyboard takes real time, and a software-rendered browser on a busy machine reads the HUD slowly.
30	test.describe.configure({ timeout: 180_000 });
31	
32	const centre = (tileX: number, tileY: number) => ({ x: tileX * TILE + TILE / 2, y: tileY * TILE + TILE / 2 });
33	const SIGHT = SIGHT_RADIUS_TILES * TILE;
34	
35	test("sail around a shoal to an island dock and dock there [scenario:sail-and-dock]", async ({ page, request }, testInfo) => {
36	  // Palm Key's south dock sits in a corner of the shore: land beside it to the west in its row, open sea to the east,
37	  // and the coast running on east of it one row further north. A shoal bar lies across the water south of it.
38	  const palm = seaMap.islands.findIndex((island) => island.name === "Palm Key");
39	  const dock = seaMap.docks.find((each) => each.island === palm && each.side === "S")!;
40	  expect(terrainAt(seaMap, dock.tileX - 1, dock.tileY)).toBe(Terrain.Land);
41	  for (let tileX = dock.tileX + 1; tileX <= dock.tileX + 3; tileX++) expect(terrainAt(seaMap, tileX, dock.tileY)).toBe(Terrain.Sea);
42	  for (let tileX = dock.tileX; tileX <= dock.tileX + 4; tileX++) expect(terrainAt(seaMap, tileX, dock.tileY - 1)).toBe(Terrain.Land);
43	  const start = { tileX: dock.tileX, tileY: dock.tileY + 14 };
44	  // The straight course from the start to the dock runs over the shoal.
45	  const shoalOnCourse = Array.from({ length: start.tileY - dock.tileY }, (_, step) => terrainAt(seaMap, dock.tileX, dock.tileY + 1 + step));
46	  expect(shoalOnCourse).toContain(Terrain.Shoal);
47	  const shoalRows = shoalOnCourse.flatMap((kind, step) => (kind === Terrain.Shoal ? [dock.tileY + 1 + step] : []));
48	  let shoalEnd = dock.tileX;
49	  while (terrainAt(seaMap, shoalEnd + 1, shoalRows[0]!) === Terrain.Shoal) shoalEnd++;
50	
51	  const code = await createMatch(page);
52	  await place(request, page, code, start.tileX, start.tileY, compassHeading("N"));
53	  await expect(page.getByTestId("hud-dock")).toHaveText("at sea");
54	  // Round the east end of the shoal, then come up to the last waypoint: two tiles east of the dock, toward the open
55	  // side, and three tiles out.
56	  const approach = { tileX: dock.tileX + 2, tileY: dock.tileY + 3 };
57	  const waypoints = [
58	    { tileX: shoalEnd + 3, tileY: shoalRows.at(-1)! + 2 },
59	    { tileX: shoalEnd + 3, tileY: shoalRows[0]! - 2 },
60	    { tileX: approach.tileX, tileY: shoalRows[0]! - 2 },
61	    approach,
62	  ];
63	  // sailTo steers in straight lines: every leg is open sea for a hull's width.
64	  [start, ...waypoints].slice(1).forEach((point, index) => {
65	    const from = [start, ...waypoints][index]!;
66	    expect(clearCourse(centre(from.tileX, from.tileY), centre(point.tileX, point.tileY)), `leg ${index}`).toBe(true);
67	  });
68	
69	  // The minimap's fog before sailing. Wait until the ship is drawn at the start: the jump from the spawn slot is drawn
70	  // as a fast glide that clears fog on its way, so only what is still fogged now can be cleared by sailing. The
71	  // candidates are open-sea tiles out of sight of the start but well within sight of a waypoint (so their minimap
72	  // pixel, which blends a tile with its neighbours, turns wholly to sea); the ones still fogged must all clear. They
73	  // lie on both sides of the course, so a glide along one line never clears them all.
74	  await expect.poll(() => ownDrawnPosition(page)).toEqual(centre(start.tileX, start.tileY));
75	  const fogAtStart = await fogRevealed(page);
76	  const beside: { tileX: number; tileY: number }[] = [];
77	  const wellWithinSight = SIGHT_RADIUS_TILES - 2;
78	  for (let tileY = dock.tileY - SIGHT_RADIUS_TILES; tileY <= start.tileY; tileY++) {
79	    for (let tileX = dock.tileX - SIGHT_RADIUS_TILES; tileX <= shoalEnd + SIGHT_RADIUS_TILES + 3; tileX++) {
80	      const openSea = [-1, 0, 1].every((dy) => [-1, 0, 1].every((dx) => terrainAt(seaMap, tileX + dx, tileY + dy) === Terrain.Sea));
81	      const outOfSightAtStart = (tileX - start.tileX) ** 2 + (tileY - start.tileY) ** 2 > (SIGHT_RADIUS_TILES + 1) ** 2;
82	      const nearRoute = waypoints.some((point) => (tileX - point.tileX) ** 2 + (tileY - point.tileY) ** 2 <= wellWithinSight ** 2);
83	      const offTheBerth = (tileX - dock.tileX) ** 2 + (tileY - dock.tileY) ** 2 >= 5 * 5;
84	      if (openSea && outOfSightAtStart && nearRoute && offTheBerth) beside.push({ tileX, tileY });
85	    }
86	  }
87	  expect(beside.some((tile) => tile.tileX < start.tileX) && beside.some((tile) => tile.tileX > start.tileX)).toBe(true);
88	  const foggedAtStart = await minimapShows(page, beside, FOG_COLOR);
89	  const stillFogged = beside.filter((_, index) => foggedAtStart[index]);
90	  expect(stillFogged.length).toBeGreaterThan(0);
91	
92	  // Round the shoal with the keyboard.
93	  const visited: { x: number; y: number }[] = [];
94	  const record = (ship: { x: number; y: number }) => visited.push(ship);
95	  const fogAlong = [fogAtStart];
96	  for (const point of waypoints) {
97	    await sailTo(page, centre(point.tileX, point.tileY), { within: TILE, onReadout: record });
98	    fogAlong.push(await fogRevealed(page));
99	  }
100	  const berth = centre(dock.tileX, dock.tileY);
101	
102	  // The run in: at rest, turn to a fixed heading one or two units west of north, toward the land beside the dock, then
103	  // hold ahead and E together. The ship moors, at whatever speed, on the first step it is within the dock's reach with
104	  // a clear run to the berth; nothing is timed and no key is released on the way.
105	  const runStart = await turnTo(page, [compassHeading("N") - 2, compassHeading("N") - 1]);
106	  // It starts the run 1–3 tiles east of the dock and 2–4 tiles out, where the simulation's sweep shows it moors.
107	  expect(Math.floor(runStart.x / TILE) - dock.tileX).toBeGreaterThanOrEqual(1);
108	  expect(Math.floor(runStart.x / TILE) - dock.tileX).toBeLessThanOrEqual(3);
109	  expect(Math.floor(runStart.y / TILE) - dock.tileY).toBeGreaterThanOrEqual(2);
110	  await recordDockHints(page);
111	  await page.keyboard.down("ArrowUp");
112	  await page.keyboard.down("KeyE");
113	  await expect(page.getByTestId("hud-dock")).toHaveText(dockLabel(seaMap, dock.id), { timeout: 30_000 });
114	  // Let go of ahead first: while E is held the ship stays moored whatever the throttle does.
115	  await page.keyboard.up("ArrowUp");
116	  await page.keyboard.up("KeyE");
117	  expect(dockLabel(seaMap, dock.id)).toBe("Palm Key, south dock");
118	  // The HUD shows the dock the ship is moored at.
119	  await expect(page.getByTestId("hud-dock")).toHaveAttribute("data-dock", String(dock.id));
120	  // On the way in the HUD only ever offered to dock (the ship moors the step it comes within reach, so the offer may be
121	  // too brief to draw); it never asked to slow down. Moored, it says nothing.
122	  const pressE = `Press E to dock at ${dockLabel(seaMap, dock.id)}`;
123	  for (const hint of await dockHintsSeen(page)) expect(["", pressE]).toContain(hint);
124	  await expect(page.getByTestId("hud-dock-hint")).toHaveText("");
125	
126	  // The ship stops at the dock and stays there.
127	  const self = await selfId(page);
128	  const moored = (await readout(page, self))!;
129	  expect(moored).toMatchObject({ ...berth, speed: 0, dock: dock.id });
130	  await page.waitForTimeout(500);
131	  expect(await readout(page, self)).toEqual(moored);
132	  // It went round the shoal, never over it.
133	  expect(visited.length).toBeGreaterThan(10);
134	  for (const point of visited) expect(isNavigable(seaMap, Math.floor(point.x / TILE), Math.floor(point.y / TILE))).toBe(true);
135	  expect(visited.some((point) => Math.floor(point.x / TILE) > shoalEnd)).toBe(true);
136	  await expect.poll(() => shipsOnCanvas(page)).toEqual([self]);
137	
138	  // The tile map is on the canvas: land, the shoal bar, the island's other dock and open sea each show their
139	  // placeholder colour, sampled at the tile through the camera's scroll.
140	  const island = seaMap.islands[palm]!;
141	  const otherDock = seaMap.docks.find((each) => each.island === palm && each.id !== dock.id)!;
142	  const tiles = [
143	    { name: "land", tileX: dock.tileX, tileY: dock.tileY - 4, kind: Terrain.Land, color: LAND_COLORS[island.theme] },
144	    { name: "shoal", tileX: dock.tileX, tileY: shoalRows[0]!, kind: Terrain.Shoal, color: SHOAL_COLOR },
